package com.novacommerce.order.domain.cart; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Embeddable public class CartItem {@Column(name="variant_id")private UUID variantId;@Column(nullable=false)private long quantity;@Column(name="created_at",nullable=false)private Instant createdAt;@Column(name="updated_at",nullable=false)private Instant updatedAt;protected CartItem(){}public CartItem(UUID id,long q,Instant now){variantId=id;setQuantity(q,now);createdAt=now;}public void setQuantity(long q,Instant now){if(q<1||q>999)throw new IllegalArgumentException("Quantity must be between 1 and 999");quantity=q;updatedAt=now;}public UUID getVariantId(){return variantId;}public long getQuantity(){return quantity;}}
